(function(){
  const A=window.Aura,C=window.AURA_CATALOG,root=document.getElementById('admin-app');
  const session=A.session();
  if(!session){location.replace('login.html');return;}
  let role=session.role||'admin',profile=A.role(role),view=(location.hash||'#'+profile.home).slice(1),selectedDate=A.firstBookableDate(),query='',categoryFilter='Todas',selectedClient=null;
  let toastTimer;
  const brl=A.money,esc=A.escape;
  const services=()=>A.activeServices();
  const staff=()=>A.staff();
  const appts=()=>A.get().appointments;
  const activeAppts=()=>appts().filter(a=>!['cancelado','cancelada','cancelado-profissional','falta'].includes(a.status));
  const fmtDate=A.fmtDate;
  const svcName=id=>A.service(id)?.name||'Serviço';
  const proName=id=>A.pro(id)?.name||'A definir';
  const roleItems={
    dashboard:['Visão geral','▦'],agenda:['Agenda','▤'],clientes:['Clientes','♙'],servicos:['Serviços','✧'],equipe:['Equipe','♙'],financeiro:['Financeiro','▣'],pacotes:['Pacotes e créditos','♧'],relatorios:['Relatórios','▥'],configuracoes:['Configurações','☷'],balcao:['Balcão / recepção','⌂'],fila:['Fila de espera','◷'], 'minha-agenda':['Minha agenda','▦'],disponibilidade:['Disponibilidade','◷']
  };
  function toast(m){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el);}el.textContent=m;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700);}
  function title(t,s,buttons=''){return `<div class="page-title"><div><h1>${t}</h1><p>${s}</p></div><div class="row" style="justify-content:flex-end;flex-wrap:wrap">${buttons}</div></div>`;}
  function side(){return `<aside class="sidebar"><div class="sidebar-brand"><div><div class="brand-word">aurá</div><div class="brand-sub">beleza & estética</div></div></div><div class="sidebar-kicker">Espaço de gestão</div><nav class="side-nav">${profile.permissions.map(key=>{const it=roleItems[key];return it?`<a href="#${key}" class="${view===key?'active':''}"><span class="nav-icon">${it[1]}</span>${it[0]}${key==='agenda'?'<span class="side-count">'+activeAppts().length+'</span>':''}</a>`:''}).join('')}</nav><div class="sidebar-bottom"><strong>Unidade Jardins</strong>Operação integrada<br>Ter–sáb · 9h às 19h<br><span style="display:block;margin-top:10px;color:#fff">${esc(profile.label)}</span>${esc(session.name||profile.name)}<button class="link small" style="display:block;color:#ead4df;margin-top:9px" data-action="reset-demo">Reiniciar demonstração</button></div></aside>`;}
  function topbar(){return `<header class="admin-topbar"><div class="breadcrumbs">Gestão&nbsp; / &nbsp;<b>${esc(roleItems[view]?.[0]||'Gestão')}</b></div><div class="admin-top-actions"><input class="header-search" id="global-search" placeholder="Buscar cliente, serviço ou reserva…" value="${esc(query)}"><div class="admin-user"><span class="avatar">${esc((session.name||profile.name).slice(0,1))}</span><span class="user-label"><strong>${esc(session.name||profile.name)}</strong><br><small class="muted">${esc(profile.label)}</small></span></div><button class="btn ghost small" data-action="logout">Sair</button></div></header>`;}
  function layout(content){root.innerHTML=`<div class="admin-shell">${side()}<div class="admin-main">${topbar()}<main class="admin-content">${content}<div class="footer" style="margin:30px -28px -44px"><div class="footer-inner"><span>aurá · Espaço de gestão</span><span>Dados demonstrativos · Protótipo acadêmico sem back-end</span></div></div></main></div></div>`;}
  function stat(label,value,note,extra=''){return `<article class="stat-card ${extra}"><div class="stat-label">${label}</div><div class="stat-number">${value}</div><div class="stat-note">${note}</div></article>`;}
  function miniBars(){const vals=[36,42,55,40,48];return `<div class="bar-chart">${vals.map((v,i)=>`<div class="bar-item ${i===4?'active':''}"><b>${v}</b><i style="height:${v/60*100}%"></i><small>${['Ter','Qua','Qui','Sex','Sáb'][i]}</small></div>`).join('')}</div>`;}
  function queuePanel(){const q=A.get().queue.filter(x=>x.status==='aguardando').sort((a,b)=>a.arrivalAt.localeCompare(b.arrivalAt));return `<section class="panel"><div class="panel-head"><div><h2>Na recepção</h2><p>Fila presencial · ordem de chegada</p></div><span class="pill gold">${q.length} na fila</span></div><div class="queue-list">${q.slice(0,4).map((x,i)=>`<div class="queue-item"><span class="queue-index">0${i+1}</span><div><strong>${esc(x.name)}</strong><small>${esc(svcName(x.serviceId))}</small></div><span class="queue-time">${esc(x.arrivalAt)}</span></div>`).join('')||'<p class="small muted">Fila vazia no momento.</p>'}</div><a class="link small" href="#fila">Ver fila completa →</a></section>`;}
  function overview(){
    const todayCount=activeAppts().filter(a=>a.date===selectedDate).length;
    return `${title('Um bom dia começa com cuidado.','Sua operação integrada em um só lugar.',`<input type="date" class="control" style="width:auto" value="${selectedDate}" data-action="overview-date"><a href="#balcao" class="btn">+ Novo agendamento</a>`)}<div class="grid four">${stat('Agendamentos hoje','48',`${todayCount} registros na amostra · referência visual do Figma`)}${stat('Receita prevista','R$ 9.840','Visão do dia · dado ilustrativo', '')}${stat('Ocupação da agenda','82%','Meta gerencial ilustrativa de 70%','highlight')}${stat('Clientes em atendimento','12','Indicador ilustrativo · Figma','')}</div><div class="admin-grid"><section class="panel"><div class="panel-head"><div><h2>Ritmo da semana</h2><p>Agendamentos dos últimos 5 dias de atendimento.</p></div><span class="pill gray">Agenda integrada</span></div>${miniBars()}</section>${queuePanel()}</div><div class="admin-grid"><section class="panel"><div class="panel-head"><div><h2>A seguir na agenda</h2><p>${fmtDate(selectedDate)} · Próximos atendimentos</p></div><a href="#agenda" class="link small">Todos os agendamentos →</a></div>${apptTable(activeAppts().filter(a=>a.date===selectedDate).slice().sort((a,b)=>a.start.localeCompare(b.start)).slice(0,6),false)}</section><div class="stack"><div class="panel" style="background:#f1e5eb"><h2 style="font:500 22px var(--serif);margin:0 0 8px">Cada detalhe faz a diferença.</h2><p class="small">Avaliações prévias devem ser confirmadas antes de procedimentos específicos. Créditos próximos do vencimento exigem atenção da recepção.</p><a href="#configuracoes" class="link small">Revisar pendências →</a></div><div class="panel"><h2 style="font:500 20px var(--serif);margin:0 0 5px">Uma equipe, o mesmo cuidado.</h2><p class="small muted">${staff().filter(p=>p.role==='Profissional').length} profissionais demonstrativos na amostra.<br>Dimensionamento previsto no documento: 38 a 50 colaboradores, CLT, escala 5 × 2.</p></div></div></div><div class="notice sand" style="margin-top:16px">Os números do painel são demonstrativos. A referência visual do Figma mostra 48 agendamentos, receita prevista de R$ 9.840 e ocupação de 82%; estes indicadores não representam dados reais da clínica.</div>`;
  }
  function apptTable(list,actions=true,professional=false){
    if(!list.length)return `<div class="empty-state">Nenhum agendamento encontrado para este filtro.</div>`;
    return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Horário</th><th>Cliente / serviço</th><th>Profissional</th><th>Valor</th><th>Status</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${list.map(a=>`<tr><td><strong>${esc(a.start)}</strong><span class="table-secondary">${esc(fmtDate(a.date))}</span></td><td><strong>${esc(a.customer)}</strong><span class="table-secondary">${a.services.map(x=>esc(svcName(x.serviceId))).join(' + ')}</span></td><td>${a.services.map(x=>esc(proName(x.professionalId))).join(', ')}</td><td>${brl(a.total)}</td><td><span class="pill ${a.status==='confirmado'?'green':a.status==='em atendimento'?'gold':a.status==='concluido'?'sage':'gray'}">${esc(a.status)}</span></td>${actions?`<td><div class="row" style="justify-content:flex-start;flex-wrap:wrap"><button class="btn ghost small" data-action="view-appt" data-id="${esc(a.id)}">Detalhes</button>${a.status==='confirmado'?`<button class="btn secondary small" data-action="checkin" data-id="${esc(a.id)}">Check-in</button>${professional?'':`<button class="btn ghost small" data-action="no-show" data-id="${esc(a.id)}">Registrar falta*</button>`}`:''}${a.status==='em atendimento'?`<button class="btn small" data-action="finish" data-id="${esc(a.id)}">Concluir</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;
  }
  function scheduleGrid(date){const cols=staff().filter(p=>p.role==='Profissional').slice(0,4),day=activeAppts().filter(a=>a.date===date);return `<div class="agenda-scroll"><div class="agenda-grid"><div class="agenda-head">Horário</div>${cols.map(p=>`<div class="agenda-head">${esc(p.name)}<small>${esc(p.specialties[0]||'')}</small></div>`).join('')}${Array.from({length:10},(_,i)=>{const hour=9+i;return `<div class="agenda-time">${String(hour).padStart(2,'0')}:00</div>${cols.map(p=>{const ev=day.flatMap(a=>a.services.map(it=>({a,it}))).filter(x=>x.it.professionalId===p.id&&Number(x.it.start.slice(0,2))===hour);return `<div class="agenda-cell">${ev.map(x=>`<button class="agenda-event" data-action="view-appt" data-id="${esc(x.a.id)}"><strong>${esc(x.a.customer)}</strong>${esc(svcName(x.it.serviceId))}<br>${esc(x.it.start)} · ${x.it.duration} min</button>`).join('')||'<span class="tiny muted">—</span>'}</div>`;}).join('')}`;}).join('')}</div></div>`;}
  function agenda(){
    const date=selectedDate;const day=activeAppts().filter(a=>a.date===date).sort((a,b)=>a.start.localeCompare(b.start));
    return `${title('Agenda, sem desencontros.','Profissionais, espaços e serviços no mesmo ritmo.',`<button class="btn secondary" data-action="queue-shortcut">Fila de espera · ${A.get().queue.filter(x=>x.status==='aguardando').length}</button><a href="#balcao" class="btn">+ Novo agendamento</a>`)}<div class="agenda-toolbar"><div class="row"><button class="icon-btn" data-action="day-shift" data-shift="-1">‹</button><input type="date" class="control" style="width:auto" value="${date}" data-action="agenda-date"><button class="icon-btn" data-action="day-shift" data-shift="1">›</button><span class="small muted">${fmtDate(date)}</span></div><div class="row"><span class="pill gray">Grade de ${A.get().config.grid} min</span><span class="pill sage">Higienização ${A.get().config.cleaning} min</span></div></div><section class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>Grade de profissionais</h2><p>Visão diária por profissional · grade demonstrativa de 60 minutos.</p></div></div>${scheduleGrid(date)}</section><div class="admin-grid"><section class="panel"><div class="panel-head"><div><h2>Atendimentos do dia</h2><p>Selecione um registro para ver os detalhes.</p></div><span class="pill">${day.length} reservas</span></div>${apptTable(day,true,role==='profissional')}</section><div class="stack"><section class="panel"><h2 style="font:500 23px var(--serif);margin:0 0 10px">Agenda por profissional</h2>${staff().filter(p=>p.role==='Profissional').map(p=>{const n=day.filter(a=>a.services.some(s=>s.professionalId===p.id)).length;return `<div class="metric-line"><span style="min-width:115px">${esc(p.name)}</span><div class="metric-track"><i style="width:${Math.min(100,n*25)}%"></i></div><strong>${n}</strong></div>`;}).join('')}</section>${queuePanel()}</div></div><div class="notice sand" style="margin-top:15px">A escala e a agenda são demonstrativas. A alocação deve respeitar especialidade, disponibilidade individual e higienização. Não há integração com calendário externo.</div>`;
  }
  function clients(){
    const all=appts().filter(a=>a.customer).reduce((acc,a)=>{const k=a.cpf||a.customer.toLowerCase();acc[k]=acc[k]||{name:a.customer,phone:a.phone||'—',email:a.email||'—',cpf:a.cpf||'—',appointments:[]};acc[k].appointments.push(a);return acc;},{});
    const list=Object.values(all).filter(c=>!query||`${c.name} ${c.phone} ${c.email} ${c.cpf}`.toLowerCase().includes(query.toLowerCase()));
    if(selectedClient){const c=list.find(x=>(x.cpf==='—'?x.name:x.cpf)===selectedClient)||list.find(x=>x.name===selectedClient);if(c){const rows=c.name==='Isabela Martins'?[['20 nov, 2026','Massagem relaxante','Patrícia Nunes','R$ 180,00','Falta registrada'],['07 nov, 2026','Limpeza de pele','Juliana Rocha','R$ 180,00','Concluído'],['22 out, 2026','Corte + escova','Carolina Melo','R$ 210,00','Concluído']]:c.appointments.map(a=>[fmtDate(a.date),a.services.map(x=>svcName(x.serviceId)).join(' + '),a.services.map(x=>proName(x.professionalId)).join(', '),brl(a.total),a.status]);return `${title('Cliente por inteiro.','Clientes / '+esc(c.name)+' · Um histórico de cuidado, não apenas de visitas.',`<button class="btn secondary" data-action="back-clients">← Voltar aos clientes</button><a href="#balcao" class="btn">+ Agendar serviço</a>`)}<div class="admin-grid"><section class="panel"><span class="eyebrow">Cliente Aurá · ficha demonstrativa</span><h2 class="serif" style="font-size:32px;margin:8px 0">${esc(c.name)}</h2><span class="pill sage">Cadastro ${c.cpf==='—'?'demonstrativo':'identificado'}</span><div class="divider"></div><div class="stack small"><div><span class="eyebrow">CPF</span><p>${c.cpf==='—'?'***.482.***-**':esc(c.cpf)}</p></div><div><span class="eyebrow">Celular</span><p>${esc(c.phone)}</p></div><div><span class="eyebrow">E-mail</span><p>${esc(c.email)}</p></div><div><span class="eyebrow">Cliente desde</span><p>Março de 2025 · dado ilustrativo</p></div></div><div class="divider"></div><strong>Privacidade em primeiro lugar</strong><p class="small muted">Acesso clínico restrito à equipe autorizada. Consentimento e anamnese devem ser consultados conforme permissões.</p></section><div class="stack"><div class="grid three">${stat('Atendimentos concluídos',c.name==='Isabela Martins'?'18':c.appointments.length,'Histórico demonstrativo')}${stat('Em cuidados realizados',c.name==='Isabela Martins'?'R$ 4.260':brl(c.appointments.reduce((n,x)=>n+x.total,0)),'Valor ilustrativo')}${stat('Próximo atendimento',c.name==='Isabela Martins'?'Hoje, 10:45':'A consultar','Agenda demonstrativa')}</div>${c.name==='Isabela Martins'?'<div class="notice sand"><strong>Atenção antes do atendimento:</strong> sensibilidade a fragrâncias registrada. Confirmar produtos na anamnese.</div>':''}<section class="panel"><h2>Uma trajetória de cuidado</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Serviço / profissional</th><th>Valor pago</th><th>Situação</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}</td><td><strong>${esc(r[1])}</strong><span class="table-secondary">${esc(r[2])}</span></td><td>${esc(r[3])}</td><td><span class="pill gray">${esc(r[4])}</span></td></tr>`).join('')}</tbody></table></div></section><div class="notice sage">Anamnese e termos devem ser verificados antes de serviços que exigem avaliação prévia. Este prontuário é apenas uma representação visual fictícia.</div></div></div>`;}}
    return `${title('Clientes por inteiro.','Cadastro, histórico de cuidado e informações necessárias ao atendimento.',`<span class="pill sage">${Object.keys(all).length} clientes na amostra</span>`)}<div class="toolbar"><div class="searchbox"><span>⌕</span><input id="client-search" placeholder="Buscar nome, CPF ou telefone…" value="${esc(query)}"></div></div><section class="panel">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>CPF</th><th>Celular</th><th>Atendimentos</th><th>Último registro</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.name)}</strong><span class="table-secondary">${esc(c.email)}</span></td><td>${esc(c.cpf)}</td><td>${esc(c.phone)}</td><td>${c.appointments.length}</td><td>${esc(fmtDate(c.appointments.slice().sort((a,b)=>b.date.localeCompare(a.date))[0].date))}</td><td><button class="btn ghost small" data-action="client-detail" data-key="${esc(c.cpf==='—'?c.name:c.cpf)}">Abrir ficha</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Nenhum cliente para exibir. Novas reservas aparecerão aqui.</div>'}</section><div class="notice sand" style="margin-top:15px">Acesso a dados clínicos e anamnese deve ser restrito por perfil. Este protótipo utiliza apenas nomes e registros fictícios.</div>`;
  }
  function servicesPage(){
    const list=services().filter(s=>(categoryFilter==='Todas'||s.category===categoryFilter)&&(!query||`${s.name} ${s.group} ${s.description}`.toLowerCase().includes(query.toLowerCase())));
    return `${title('Beleza em cada detalhe.','Catálogo de serviços · valores sugeridos no Figma, sujeitos à aprovação.',`<span class="pill">${C.counts.total} itens de referência</span>`)}<div class="toolbar"><div class="searchbox"><span>⌕</span><input id="service-search" value="${esc(query)}" placeholder="Buscar serviço…"></div><select id="service-category">${['Todas',...C.categories.map(x=>x.id)].map(x=>`<option ${categoryFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="btn secondary small" data-action="new-service">+ Novo serviço</button></div><div class="row" style="justify-content:flex-start;gap:7px;flex-wrap:wrap;margin-bottom:12px">${C.categories.map(c=>`<span class="pill gray">${esc(c.label)} · ${C.counts[c.id]}</span>`).join('')}</div><section class="panel"><div class="catalog-admin-list">${list.map(s=>{const o=A.get().serviceOverrides?.[s.id]||{};return `<div class="catalog-admin-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.category)} · ${esc(s.group)} ${s.evaluation?'· exige avaliação prévia':''}</small></div><div><small>Preço sugerido</small><input aria-label="Preço de ${esc(s.name)}" type="number" min="0" step="0.01" data-price="${esc(s.id)}" value="${Number(o.price??s.price??0)}"></div><div class="catalog-col-extra"><small>Duração demo. (min)</small><input type="number" min="15" step="15" data-duration="${esc(s.id)}" value="${Number(o.duration??s.duration)}"></div><div><span class="status-dot ${A.get().inactiveServices.includes(s.id)?'off':''}"></span><button class="link small" data-action="toggle-active" data-id="${esc(s.id)}">${A.get().inactiveServices.includes(s.id)?'Ativar':'Ativo'}</button></div></div>`;}).join('')||'<div class="empty-state">Nenhum serviço encontrado.</div>'}</div></section><div class="notice sand" style="margin-top:14px">A página 9 do Figma apresenta 83 serviços e preços sugeridos. Durações aqui exibidas são estimativas de simulação, não definidas no levantamento. O item “Remoção de pontas duplas” consta como pendente porque o preço não está legível no PDF.</div>`;
  }
  function team(){
    return `${title('Uma equipe, o mesmo cuidado.','Profissionais, especialidades, escalas e alocação.',`<button class="btn secondary" data-action="record-absence">Registrar ausência</button><button class="btn" data-action="new-member">+ Adicionar pessoa</button>`)}<div class="grid four">${stat('Profissionais cadastrados',staff().filter(p=>p.role==='Profissional').length,'Amostra demonstrativa')}${stat('Quadro previsto','38–50','Porte definido no levantamento')}${stat('Regime','CLT','Escala 5 × 2')}${stat('Operação','Ter–sáb','09h às 19h')}</div><div class="profile-list" style="margin-top:16px">${staff().map(p=>`<article class="profile-card"><span class="avatar">${esc(p.name.charAt(0))}</span><div style="flex:1"><strong>${esc(p.name)}</strong><small>${esc(p.specialties.join(' · '))}</small><small>${esc(p.shift||'Escala a definir')} · ${esc(p.contract||'CLT')}</small></div><span class="pill gray">${esc(p.role)}</span></article>`).join('')}</div><div class="notice sage" style="margin-top:16px">Para contratos CLT, a tela do profissional mostra alocação e agenda; não exibe ganho diário por hora. Em caso de falta, a gerência decide a substituição. Reservas com profissional escolhido são canceladas e comunicadas; as sem preferência podem ser realocadas para outro profissional da especialidade.</div>`;
  }
  function finance(){
    const list=appts().filter(a=>a.paymentStatus&&a.status!=='cancelado');const gross=list.reduce((n,a)=>n+Number(a.charged??a.total??0),0);const pix=list.filter(a=>a.paymentMethod==='Pix').reduce((n,a)=>n+(a.charged??a.total??0),0);const card=list.filter(a=>String(a.paymentMethod).includes('Cartão')).reduce((n,a)=>n+(a.charged??a.total??0),0);
    return `${title('Resultados que florescem.','Recebimentos, créditos e saúde financeira com clareza.',`<button class="btn secondary" data-action="export-finance">↓ Exportar relatório</button>`)}<div class="grid four">${stat('Recebido hoje','R$ 6.240','30 pagamentos confirmados · referência Figma')}${stat('A receber hoje','R$ 3.600','18 pagamentos pendentes · referência Figma')}${stat('Créditos ativos','R$ 1.080','12 clientes · dado demonstrativo')}${stat('Margem líquida','30,4%','Meta gerencial ilustrativa','sage')}</div><div class="admin-grid"><section class="panel"><h2>Como suas clientes pagam</h2><p class="small muted">Recebimentos do dia · R$ 6.240,00 · cenário do Figma.</p>${[['Pix',45,'R$ 2.808'],['Cartões',40,'R$ 2.496'],['Espécie',15,'R$ 936']].map(x=>`<div class="metric-line"><span>${x[0]}</span><div class="metric-track"><i style="width:${x[1]}%"></i></div><strong>${x[2]}</strong></div>`).join('')}</section><section class="panel"><h2>Crescer com equilíbrio</h2><p class="small muted">Cenário ilustrativo de faturamento.</p>${[['Folha + encargos + comissões',43],['Outras despesas',26.6],['Margem líquida',30.4]].map(x=>`<div class="metric-line"><span>${x[0]}</span><div class="metric-track"><i style="width:${x[1]}%"></i></div><strong>${x[1]}%</strong></div>`).join('')}</section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>Movimentações recentes</h2><p>Pagamentos simulados e reservas cadastradas.</p></div></div>${apptTable(list.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,10),false)}</section><div class="notice sand" style="margin-top:14px">Os valores no Figma são um cenário demonstrativo. A integração com gateway, emissão fiscal e contabilidade está apenas planejada e não é executada neste protótipo.</div>`;
  }
  function packages(){
    const pk=A.get().packages;
    return `${title('Pacotes e créditos.','A equipe de marketing define os serviços, vigência, desconto e data de publicação.',`<button class="btn" data-action="new-package">+ Criar pacote</button>`)}<div class="grid three">${pk.map(p=>`<article class="card"><span class="pill ${p.status==='publicado'?'green':'gold'}">${esc(p.status)}</span><h2 class="serif" style="font-size:25px">${esc(p.name)}</h2><p class="small muted">${(p.serviceIds||[]).map(id=>esc(svcName(id))).join(' + ')}</p><div class="summary-line"><span>Desconto</span><strong>${p.discount}%</strong></div><div class="summary-line"><span>Vigência</span><strong>${esc(p.startDate)}–${esc(p.endDate)}</strong></div><div class="summary-line"><span>Exibição a partir de</span><strong>${esc(p.publishDate)}</strong></div><button class="btn secondary full small" data-action="toggle-package" data-id="${esc(p.id)}">${p.status==='publicado'?'Retirar publicação':'Publicar pacote'}</button></article>`).join('')||`<div class="card empty-state"><div class="symbol">✧</div><h2 class="serif">Nenhum pacote cadastrado.</h2><p>Cadastre um pacote de exemplo. Composição, preço, validade e regras de uso seguem como decisões a validar.</p></div>`}</div><div class="notice sand" style="margin-top:16px"><strong>Orientação da aula de 16/11:</strong> o cadastro deve informar serviços incluídos, período de vigência, desconto e data a partir da qual o pacote será exibido. O pacote é criado pelo marketing, não pelo profissional. A validade de uso e as regras de sessões/transferência continuam pendentes de decisão.</div><div class="panel" style="margin-top:16px"><h2>Créditos de clientes</h2>${A.get().credits.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>CPF vinculado</th><th>Valor</th><th>Motivo</th><th>Vencimento</th><th>Transferência</th></tr></thead><tbody>${A.get().credits.map(c=>`<tr><td>${esc(c.cpf)}</td><td>${brl(c.amount)}</td><td>${esc(c.reason)}</td><td>${esc(c.expiresAt)}</td><td>Intransferível</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Nenhum crédito foi gerado nesta sessão.</p>'}</div>`;
  }
  function reports(){
    const all=appts(),noShows=all.filter(a=>a.status==='falta').length,cancels=all.filter(a=>String(a.status).includes('cancelado')).length,credits=A.get().credits.reduce((n,c)=>n+c.amount,0);
    return `${title('Relatórios para decidir melhor.','Indicadores de ocupação, receita, faltas, espera e créditos.',`<button class="btn secondary" data-action="export-reports">↓ Exportar dados</button>`)}<div class="grid four">${stat('Agendamentos',all.length,'Reservas nesta demonstração')}${stat('Faltas registradas',noShows,'Registro manual pela recepção')}${stat('Cancelamentos',cancels,'Inclui cancelamentos por ausência do profissional')}${stat('Créditos ativos',brl(credits),'Validade padrão de 7 dias')}</div><div class="admin-grid"><section class="panel"><h2>Ocupação por especialidade</h2>${C.categories.map(c=>{const n=all.reduce((sum,a)=>sum+a.services.filter(s=>A.service(s.serviceId)?.category===c.id).length,0);return `<div class="metric-line"><span style="min-width:125px">${esc(c.label)}</span><div class="metric-track"><i style="width:${Math.min(100,n*12)}%"></i></div><strong>${n}</strong></div>`;}).join('')}</section><section class="panel"><h2>Experiência de atendimento</h2><p class="small muted">Dados ilustrativos para a apresentação.</p>${[['Taxa de ocupação',82],['Chegada no horário',91],['Confirmação de avaliação',76]].map(x=>`<div class="metric-line"><span>${x[0]}</span><div class="metric-track"><i style="width:${x[1]}%"></i></div><strong>${x[1]}%</strong></div>`).join('')}</section></div><div class="notice sand" style="margin-top:16px">Aula de 16/11: relatórios precisam acompanhar também os dados de fidelidade/cashback caso o grupo decida implementar esse recurso. A proposta de cashback por consumo é conceitual, ainda não aprovada.</div>`;
  }
  function settings(){
    const c=A.get().config;
    const pending=[
      ['11','Encadeamento de vários serviços','O protótipo permite sequência demonstrativa, mas regra final de intervalos, profissionais diferentes e encaixes precisa ser validada.','Pendente'],
      ['12','Composição e uso dos pacotes','A aula definiu os campos do cadastro; preço, validade de uso, sessões e transferência ainda precisam de decisão.','Parcial'],
      ['13','Retenção do horário durante o pagamento','Tempo de bloqueio no checkout e comportamento de falha do pagamento não foram definidos.','Pendente'],
      ['14','Cancelamento e remarcação pelo site','Prazo de 24h está na proposta do grupo/aula; exceções, limite de remarcações e cancelamento abaixo de 24h devem ser confirmados.','Parcial'],
      ['17','Alcance dos meios de pagamento','Documento registra Visa, Mastercard, Pix, débito, crédito e espécie presencial. Confirmar eventual regra de exclusividade por perfil/pacote.','Pendente'],
      ['26–27','Atraso após a tolerância','Tolerância de 15 minutos está no protótipo; conduta exata após o limite e consequência financeira precisam de validação final.','Pendente'],
      ['34','Regras configuráveis','Definir quais parâmetros a administração poderá alterar sem programação e quem terá permissão.','Pendente']
    ];
    return `${title('O cuidado tem suas regras.','Parâmetros operacionais e decisões que ainda dependem de validação.',`<button class="btn" data-action="save-settings">Salvar parâmetros</button>`)}<form id="settings-form"><div class="admin-grid"><section class="panel"><h2>01 · Operação e disponibilidade</h2><div class="field-row"><div class="field"><label>Horário de abertura</label><input type="time" name="open" value="${c.open}"></div><div class="field"><label>Horário de encerramento</label><input type="time" name="close" value="${c.close}"></div></div><div class="field-row"><div class="field"><label>Grade de horários (min)</label><select name="grid"><option ${c.grid===15?'selected':''}>15</option><option ${c.grid===30?'selected':''}>30</option></select></div><div class="field"><label>Higienização (min)</label><select name="cleaning"><option ${c.cleaning===10?'selected':''}>10</option><option ${c.cleaning===15?'selected':''}>15</option></select></div></div><div class="field-row"><div class="field"><label>Tolerância de atraso (min)</label><input type="number" name="delay" value="${c.delay}"></div><div class="field"><label>Cancelamento sem penalidade (h)</label><input type="number" name="cancellationHours" value="${c.cancellationHours}"></div></div><div class="field-row"><div class="field"><label>Retenção por falta (%)</label><input type="number" name="noShowPercent" min="0" max="100" value="${c.noShowPercent}"></div><div class="field"><label>Validade do crédito (dias)</label><input type="number" name="creditDays" value="${c.creditDays}"></div></div><div class="field"><label>Atribuição sem preferência</label><select name="assignment"><option value="menor-agenda" ${c.assignment==='menor-agenda'?'selected':''}>Profissional com menor agenda do dia (decisão da aula)</option><option value="manual">Escolha manual pela recepção</option></select></div><div class="notice sage">Funcionamento definido: terça a sábado, 9h às 19h. Higienização de 10 a 15 minutos; nesta versão, o padrão é 15 minutos.</div><h2 style="margin-top:22px">02 · Serviços que exigem avaliação prévia</h2><ul class="small muted"><li>Coloração, mechas e alisamentos.</li><li>Micropigmentação de sobrancelhas e lábios (item de escopo, não listado na tabela de 83 serviços).</li><li>Tratamentos para manchas, acne e sinais de envelhecimento.</li><li>Podologia em casos críticos.</li></ul><div class="notice sand">Anamnese, termos e contraindicações devem ser verificados por profissional habilitado. O protótipo não realiza avaliação clínica.</div></section><section class="panel"><h2>Decisões em aberto / parciais</h2><p class="small muted">Pendências visíveis para não transformar sugestões em regras aprovadas.</p><div class="rule-list">${pending.map((p,i)=>`<div class="rule-row"><span class="rule-no">${p[0]}</span><div><strong>${p[1]}</strong><p>${p[2]}</p></div><span class="pill ${p[3]==='Pendente'?'gold':'gray'}">${p[3]}</span></div>`).join('')}</div><div class="divider"></div><h2>03 · Perfis e permissões</h2><div class="stack small">${[['Cliente','Navegar, reservar, pagar e cancelar.'],['Recepção','Agendar no balcão, check-in, fila e registro de falta.'],['Profissional','Consultar agenda diária/semanal e registrar início/fim.'],['Gerência','Acompanhar agenda, equipe, alocação e ociosidade.'],['Marketing','Criar pacotes e descontos.'],['Administrador geral','Cadastrar profissionais, serviços e parâmetros.'],['TI','Apoio técnico e integrações planejadas.']].map(x=>`<div class="row"><strong>${x[0]}</strong><span class="muted" style="text-align:right;max-width:64%">${x[1]}</span></div>`).join('')}</div><div class="divider"></div><h2>04 · Integrações planejadas</h2><p class="small muted">Gateway de pagamento · WhatsApp · NFS-e · Google Agenda · e-mail/SMS. Não estão conectadas neste protótipo estático.</p></section></div></form>`;
  }
  function frontDesk(){
    return `${title('Atendimento com acolhimento.','Recepção: agende para a cliente, registre a chegada e acompanhe a fila.',`<a href="#fila" class="btn secondary">Abrir fila de espera</a>`)}<div class="admin-grid"><section class="panel"><h2>Novo agendamento no balcão</h2><p class="small muted">Pagamento realizado presencialmente em maquininha ou no caixa (simulado).</p><form id="counter-form"><div class="field"><label>Nome completo da cliente</label><input name="name" required placeholder="Nome da cliente"></div><div class="field-row"><div class="field"><label>CPF (11 dígitos)</label><input name="cpf" required minlength="11" maxlength="14" placeholder="000.000.000-00"></div><div class="field"><label>Celular</label><input name="phone" placeholder="(00) 90000-0000"></div></div><div class="field"><label>Serviço</label><select name="service" required>${services().map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${brl(s.price)}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label>Profissional</label><select name="professional"><option value="">Sem preferência · menor agenda</option>${staff().filter(p=>p.role==='Profissional').map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Data</label><input type="date" name="date" value="${selectedDate}" required></div></div><div class="field-row"><div class="field"><label>Horário</label><select name="start">${Array.from({length:41},(_,i)=>`<option>${A.time(540+i*15)}</option>`).join('')}</select></div><div class="field"><label>Forma de pagamento</label><select name="method"><option>Cartão de crédito</option><option>Cartão de débito</option><option>Pix</option><option>Espécie</option></select></div></div><button class="btn full">Confirmar agendamento (simulado)</button></form></section><section class="stack">${queuePanel()}<div class="panel"><h2>Rotina de recepção</h2><ol class="small muted"><li>Registrar a chegada e incluir na fila presencial por ordem de chegada.</li><li>Se houver encaixe, chamar a cliente; se não houver, orientar remarcação/restituição.</li><li>Ao final do horário, registrar manualmente o não comparecimento.</li><li>Para atraso, respeitar a tolerância configurada e buscar encaixe conforme disponibilidade.</li></ol></div></section></div>`;
  }
  function waitlist(){const q=A.get().queue.slice().sort((a,b)=>a.arrivalAt.localeCompare(b.arrivalAt));return `${title('Fila de espera por horário.','A ordem presencial é por chegada. Uma vaga liberada atende a fila daquele horário, sem antecipação em cascata.',`<button class="btn" data-action="add-queue">+ Registrar chegada</button>`)}<div class="notice sage" style="margin-bottom:14px">A fila presencial é organizada por ordem de chegada. A fila virtual por horário é uma decisão operacional a validar; esta tela simula o controle pela recepção.</div><section class="panel">${q.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Ordem</th><th>Chegada</th><th>Cliente</th><th>Serviço</th><th>Preferência</th><th>Status</th><th>Ação</th></tr></thead><tbody>${q.map((x,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(x.arrivalAt)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(svcName(x.serviceId))}</td><td>${esc(proName(x.preferredProfessional)||'Sem preferência')}</td><td><span class="pill ${x.status==='aguardando'?'gold':'green'}">${esc(x.status)}</span></td><td>${x.status==='aguardando'?`<button class="btn secondary small" data-action="call-queue" data-id="${esc(x.id)}">Chamar</button><button class="btn ghost small" data-action="queue-no-fit" data-id="${esc(x.id)}">Sem encaixe</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Fila vazia.</div>'}</section><div class="notice sand" style="margin-top:14px">Se o salão não conseguir encaixar um cliente que compareceu, a regra discutida em aula prevê devolução integral ou crédito escolhido pelo cliente. A recepção deve registrar a presença na fila.</div>`;}
  function professionalSchedule(){
    const employee=A.pro(session.employeeId)||staff().find(p=>p.role==='Profissional');const date=selectedDate;const day=activeAppts().filter(a=>a.date===date&&a.services.some(it=>it.professionalId===employee?.id)).sort((a,b)=>a.start.localeCompare(b.start));
    return `${title(`Olá, ${esc(employee?.name||'profissional')}.`,'Sua agenda diária: atendimentos, horários e intervalos de higienização.',`<input type="date" class="control" style="width:auto" value="${date}" data-action="agenda-date">`)}<div class="grid three">${stat('Atendimentos no dia',day.length,'Na sua agenda')}${stat('Tempo reservado',`${day.reduce((n,a)=>n+a.services.filter(x=>x.professionalId===employee?.id).reduce((m,x)=>m+x.duration,0),0)} min`,'Alocação demonstrativa')}${stat('Contrato','CLT','Salário fixo · sem exibição de ganho diário')}</div><section class="panel" style="margin-top:16px"><h2>Minha agenda</h2>${apptTable(day,true,true)}</section><div class="notice sage" style="margin-top:14px">A rotina do profissional deve ser simples para uso em movimento. Esta simulação permite registrar início e conclusão do atendimento; não há cobrança de operação complexa durante cada serviço.</div>`;
  }
  function availability(){const p=A.pro(session.employeeId);return `${title('Minha disponibilidade.','Consulte sua escala e os horários alocados.',`<span class="pill sage">${esc(p?.shift||'Escala demonstrativa')}</span>`)}<div class="panel"><h2>Escala de trabalho</h2><p class="small muted">${esc(p?.name||session.name)} · ${esc(p?.contract||'CLT')} · ${esc(p?.specialties?.join(' / ')||'Especialidade')}</p><p>Terça a sábado · 09h às 19h · folgas conforme escala 5 × 2 configurada pela unidade.</p><div class="notice sand">A disponibilidade individual precisa ser cadastrada para geração da agenda. Os horários exibidos nesta versão são apenas demonstrativos.</div></div>`;}
  function render(){
    if(!profile.permissions.includes(view))view=profile.home;
    let content='';switch(view){case'dashboard':content=overview();break;case'agenda':content=agenda();break;case'clientes':content=clients();break;case'servicos':content=servicesPage();break;case'equipe':content=team();break;case'financeiro':content=finance();break;case'pacotes':content=packages();break;case'relatorios':content=reports();break;case'configuracoes':content=settings();break;case'balcao':content=frontDesk();break;case'fila':content=waitlist();break;case'minha-agenda':content=professionalSchedule();break;case'disponibilidade':content=availability();break;default:content=overview();}
    layout(content);
  }
  function showModal(html){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<section class="modal" role="dialog" aria-modal="true">${html}</section>`;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)m.remove();});}
  function hasConflict(list,professionalId,date,start,duration,ignoreId){const from=A.minutes(start),to=from+duration;return list.filter(x=>x.date===date&&x.id!==ignoreId&&!['cancelado','cancelado-profissional','falta'].includes(x.status)).some(x=>(x.services||[]).some(y=>y.professionalId===professionalId&&from<A.minutes(y.start)+(y.duration||60)+A.get().config.cleaning&&to>A.minutes(y.start)));}
  function counterSubmit(form){const f=new FormData(form),svc=A.service(f.get('service')),date=f.get('date'),start=f.get('start');if(!svc){toast('Serviço inválido.');return;}const candidates=(f.get('professional')?[A.pro(f.get('professional'))]:staff().filter(x=>x.specialties.includes(svc.category)).sort((a,b)=>appts().filter(x=>x.date===date&&x.services.some(y=>y.professionalId===a.id)).length-appts().filter(x=>x.date===date&&x.services.some(y=>y.professionalId===b.id)).length)).filter(Boolean);const p=candidates.find(x=>x.specialties.includes(svc.category)&&!hasConflict(appts(),x.id,date,start,svc.duration));if(!p){toast('Não há profissional livre neste horário. Escolha outro horário ou profissional.');return;}if(A.minutes(start)+svc.duration>A.minutes(A.get().config.close)){toast('O serviço ultrapassa o horário de funcionamento.');return;}
    const ap={id:'BAL-'+Date.now().toString().slice(-6),bookingId:'BAL-'+Date.now().toString().slice(-6),customer:String(f.get('name')).trim(),cpf:String(f.get('cpf')).replace(/\D/g,''),phone:String(f.get('phone')||''),email:'',date,start,services:[{serviceId:svc.id,professionalId:p.id,professionalMode:f.get('professional')?'chosen':'auto',start,duration:svc.duration}],total:svc.price,charged:svc.price,paymentMethod:f.get('method'),paymentStatus:'Aprovado (simulado)',status:'confirmado',source:'recepção',isDemo:false,createdAt:new Date().toISOString(),notes:'Criado no balcão; pagamento simulado.'};
    A.update(s=>s.appointments.push(ap));toast('Agendamento de balcão confirmado.');form.reset();render();
  }
  function newQueueSubmit(form){const f=new FormData(form);const linked=f.get('appointment')||'';const ap=linked?appts().find(x=>x.id===linked):null;const it={id:'Q-'+Date.now(),name:String(f.get('name')).trim(),serviceId:f.get('service'),preferredProfessional:f.get('professional')||'',appointmentId:linked,cpf:ap?.cpf||String(f.get('cpf')||'').replace(/\D/g,''),amount:ap?.charged??ap?.total??0,arrivalAt:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),status:'aguardando',isDemo:false};A.update(s=>s.queue.push(it));toast('Cliente incluída na fila por ordem de chegada.');render();}
  function createPackage(form){const f=new FormData(form);const ids=f.getAll('services');if(!ids.length){toast('Selecione ao menos um serviço.');return;}const p={id:'PK-'+Date.now(),name:String(f.get('name')).trim(),serviceIds:ids,discount:Number(f.get('discount')||0),startDate:f.get('start'),endDate:f.get('end'),publishDate:f.get('publish'),status:f.get('publish')<=A.today()?'publicado':'rascunho',createdAt:new Date().toISOString(),createdBy:'Marketing',approval:'Proposta demonstrativa; requer validação da administração.'};A.update(s=>s.packages.push(p));toast('Pacote cadastrado.');render();}
  function addService(form){const f=new FormData(form);const name=String(f.get('name')).trim();const id='custom-'+Date.now();A.update(s=>s.customServices.push({id,name,category:f.get('category'),group:String(f.get('group')).trim(),price:Number(f.get('price')),duration:Number(f.get('duration')),description:'Serviço complementar cadastrado na simulação.',evaluation:f.get('evaluation')==='on',startsAt:false,active:true,priceApproved:false,durationApproved:false}));toast('Serviço complementar salvo localmente.');render();}
  function addMember(form){const f=new FormData(form);const p={id:'p-'+Date.now(),name:String(f.get('name')).trim(),role:'Profissional',specialties:[f.get('category')],category:f.get('category'),contract:'CLT',shift:'Escala a definir'};A.update(s=>s.team.push(p));toast('Pessoa adicionada à equipe demonstrativa.');render();}
  function handleAbsence(form){const f=new FormData(form),id=f.get('professional'),date=f.get('date');let changed=0,cancelled=0;A.update(s=>{s.appointments.filter(a=>a.date===date&&a.status==='confirmado').forEach(a=>{a.services.forEach(it=>{if(it.professionalId!==id)return;const svc=A.service(it.serviceId);if(it.professionalMode==='auto'){
            const replacement=s.team.filter(x=>x.id!==id&&x.specialties.includes(svc.category)&&!hasConflict(s.appointments,x.id,date,it.start,it.duration,a.id)).sort((a,b)=>s.appointments.filter(z=>z.date===date&&z.id!==a.id&&z.services.some(v=>v.professionalId===a.id)).length-s.appointments.filter(z=>z.date===date&&z.id!==b.id&&z.services.some(v=>v.professionalId===b.id)).length)[0];
            if(replacement){it.professionalId=replacement.id;it.substitute=true;it.substitutionNote='Substituição manual da gerência por ausência.';changed++;}
            else{a.status='cancelado-profissional';cancelled++;}
          }else{a.status='cancelado-profissional';cancelled++;}});if(a.status==='cancelado-profissional')a.notes='Cancelado por ausência do profissional escolhido. Cliente avisada (simulação); tentar remarcação.';});});toast(`Ausência registrada: ${changed} reserva(s) realocada(s), ${cancelled} cancelada(s) para remarcação.`);render();}
  function markNoShow(id){const a=appts().find(x=>x.id===id);if(!a)return;const refundable=Number(a.charged??a.total??0)*(100-A.get().config.noShowPercent)/100;showModal(`<span class="eyebrow">Registro manual pela recepção</span><h2>Registrar não comparecimento?</h2><p>A ausência deve ser registrada ao final do horário agendado. O sistema distingue a falta do cancelamento e do comparecimento à fila presencial.</p><div class="notice sand">Valor elegível a devolução ou crédito: <strong>${brl(refundable)}</strong>. Retenção: ${A.get().config.noShowPercent}% (${brl(Number(a.charged??a.total??0)-refundable)}).</div><div class="field" style="margin-top:14px"><label>Escolha do cliente para a parte devolvida</label><select id="noshow-choice"><option value="refund">Devolução em dinheiro (simulada)</option><option value="credit">Crédito de 7 dias</option></select></div><div class="modal-actions"><button class="btn ghost" data-action="close-modal">Voltar</button><button class="btn danger" data-action="confirm-no-show" data-id="${esc(id)}" data-amount="${refundable}">Registrar falta</button></div>`);}
  function detail(id){const a=appts().find(x=>x.id===id);if(!a)return;showModal(`<span class="eyebrow">Detalhes do agendamento</span><h2>${esc(a.customer)}</h2><p>${esc(fmtDate(a.date))} · ${esc(a.start)} · ${esc(a.source||'site')}</p><div class="notice sage">${a.services.map(it=>`${esc(svcName(it.serviceId))} · ${esc(proName(it.professionalId))} · ${it.start}`).join('<br>')}</div><div class="summary-line"><span>Total</span><strong>${brl(a.total)}</strong></div><div class="summary-line"><span>Pagamento</span><strong>${esc(a.paymentMethod)} · ${esc(a.paymentStatus||'')}</strong></div><div class="summary-line"><span>Status</span><strong>${esc(a.status)}</strong></div><p class="small muted">${esc(a.notes||'')}</p><div class="modal-actions"><button class="btn" data-action="close-modal">Fechar</button></div>`);}
  function exportCSV(rows,name){const csv=rows.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
    if(a==='logout'){A.clearSession();location.href='login.html';}
    if(a==='reset-demo'){if(confirm('Isso apaga as reservas, fila, créditos e pacotes criados neste navegador e restaura os dados fictícios. Continuar?')){A.reset();toast('Demonstração reiniciada.');render();}}
    if(a==='close-modal')b.closest('.modal-backdrop')?.remove();
    if(a==='view-appt')detail(b.dataset.id);
    if(a==='client-detail'){selectedClient=b.dataset.key;render();}
    if(a==='back-clients'){selectedClient=null;render();}
    if(a==='checkin'){A.update(s=>{const x=s.appointments.find(y=>y.id===b.dataset.id);if(x)x.status='em atendimento';});toast('Check-in registrado.');render();}
    if(a==='finish'){A.update(s=>{const x=s.appointments.find(y=>y.id===b.dataset.id);if(x)x.status='concluido';});toast('Atendimento concluído.');render();}
    if(a==='finish'){A.update(s=>{const x=s.appointments.find(y=>y.id===b.dataset.id);if(x)x.status='concluido';});toast('Atendimento concluído.');render();}
    if(a==='no-show')markNoShow(b.dataset.id);
    if(a==='confirm-no-show'){const choice=document.getElementById('noshow-choice')?.value||'refund',amount=Number(b.dataset.amount);A.update(s=>{const x=s.appointments.find(y=>y.id===b.dataset.id);if(x){x.status='falta';x.noShowAt=new Date().toISOString();x.refundAmount=amount;x.refundChoice=choice;x.notes=(x.notes||'')+' Falta registrada manualmente pela recepção.';if(choice==='credit')A.addCredit(x.cpf,amount,'Falta registrada · reserva '+x.id);}});b.closest('.modal-backdrop')?.remove();toast('Falta registrada e movimentação simulada criada.');render();}
    if(a==='queue-shortcut'){location.hash='#fila';}
    if(a==='call-queue'){A.update(s=>{const x=s.queue.find(y=>y.id===b.dataset.id);if(x)x.status='chamado';});toast('Cliente chamada para atendimento.');render();}
    if(a==='queue-no-fit'){const item=A.get().queue.find(x=>x.id===b.dataset.id);const amount=Number(item?.amount||0);showModal(`<h2>Sem encaixe disponível</h2><p>A cliente compareceu e foi registrada na fila. Sem possibilidade de encaixe, a regra discutida em aula prevê devolução integral ou crédito, à escolha da cliente.</p><div class="notice sage">Valor integral elegível: <strong>${brl(amount)}</strong></div><div class="field"><label>Escolha da cliente</label><select id="queue-refund-choice"><option value="refund">Devolução em dinheiro (simulada)</option><option value="credit">Crédito de 7 dias</option></select></div><div class="modal-actions"><button class="btn ghost" data-action="close-modal">Voltar</button><button class="btn" data-action="confirm-no-fit" data-id="${esc(b.dataset.id)}" data-amount="${amount}">Registrar sem encaixe</button></div>`);}
    if(a==='confirm-no-fit'){const id=b.dataset.id,amount=Number(b.dataset.amount),choice=document.getElementById('queue-refund-choice')?.value||'refund';A.update(s=>{const q=s.queue.find(x=>x.id===id);if(q){q.status='sem encaixe';q.refundAmount=amount;q.refundChoice=choice;if(q.appointmentId){const ap=s.appointments.find(x=>x.id===q.appointmentId);if(ap){ap.status='cancelado';ap.refundAmount=amount;ap.refundChoice=choice;ap.notes='Cliente compareceu, entrou na fila e não foi encaixada; devolução integral (simulação).';}}if(choice==='credit')A.addCredit(q.cpf,amount,'Compareceu à fila sem encaixe · devolução integral');}});b.closest('.modal-backdrop')?.remove();toast('Comparecimento e devolução integral registrados.');render();}
    if(a==='add-queue'){showModal(`<h2>Registrar chegada na fila</h2><p>Ordem presencial por chegada.</p><form id="queue-form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Serviço</label><select name="service">${services().map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Profissional (opcional)</label><select name="professional"><option value="">Sem preferência</option>${staff().filter(p=>p.role==='Profissional').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Reserva relacionada (se for cliente com horário marcado)</label><select name="appointment"><option value="">Sem reserva vinculada</option>${activeAppts().filter(x=>x.status==='confirmado').map(x=>`<option value="${esc(x.id)}">${esc(x.customer)} · ${esc(x.start)} · ${esc(x.id)}</option>`).join('')}</select><small>Se o salão não conseguir encaixar uma cliente que compareceu, o registro vinculado permite a devolução integral.</small></div><div class="field"><label>CPF (quando não houver reserva vinculada)</label><input name="cpf" placeholder="Somente dados fictícios"></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn">Adicionar à fila</button></div></form>`);}
    if(a==='new-package'){showModal(`<h2>Criar pacote demonstrativo</h2><p>O marketing cadastra composição, vigência, desconto e data de publicação.</p><form id="package-form"><div class="field"><label>Nome do pacote</label><input name="name" required placeholder="Ex.: Ritual de cuidado"></div><div class="field"><label>Serviços incluídos</label><select name="services" multiple required size="8">${services().map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.category)}</option>`).join('')}</select><small>Use Ctrl (Windows) ou Command (Mac) para selecionar mais de um.</small></div><div class="field-row"><div class="field"><label>Desconto (%)</label><input name="discount" type="number" min="0" max="90" value="10" required></div><div class="field"><label>Início da vigência</label><input name="start" type="date" value="${A.today()}" required></div></div><div class="field-row"><div class="field"><label>Fim da vigência</label><input name="end" type="date" value="${A.ymd(A.addDays(new Date(),30))}" required></div><div class="field"><label>Exibir a partir de</label><input name="publish" type="date" value="${A.today()}" required></div></div><div class="notice sand">A validade do pacote e regras de uso não estão definidas; este cadastro é uma simulação de estrutura, não uma regra aprovada.</div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn">Salvar pacote</button></div></form>`);}
    if(a==='toggle-package'){A.update(s=>{const p=s.packages.find(x=>x.id===b.dataset.id);if(p)p.status=p.status==='publicado'?'rascunho':'publicado';});toast('Status do pacote atualizado.');render();}
    if(a==='new-member'){showModal(`<h2>Adicionar profissional</h2><form id="member-form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Especialidade</label><select name="category">${C.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')}</select></div><div class="notice sand">Cadastro demonstrativo. Escala e disponibilidade real precisam ser informadas pela equipe.</div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn">Adicionar</button></div></form>`);}
    if(a==='record-absence'){showModal(`<h2>Registrar ausência de profissional</h2><p>A gerência decide a substituição. Reservas com profissional escolhido são canceladas para remarcação; as sem preferência tentam realocação.</p><form id="absence-form"><div class="field"><label>Profissional</label><select name="professional">${staff().filter(p=>p.role==='Profissional').map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.specialties.join('/'))}</option>`).join('')}</select></div><div class="field"><label>Data da ausência</label><input type="date" name="date" value="${selectedDate}" required></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn">Registrar e tratar agenda</button></div></form>`);}
    if(a==='export-finance'||a==='export-reports'){exportCSV([['ID','Data','Cliente','Serviços','Profissional','Valor','Forma','Status'],...appts().map(x=>[x.id,x.date,x.customer,x.services.map(s=>svcName(s.serviceId)).join(' + '),x.services.map(s=>proName(s.professionalId)).join(' + '),x.total,x.paymentMethod,x.status])],'aura-relatorio-demonstrativo.csv');}
    if(a==='save-settings'){document.getElementById('settings-form')?.requestSubmit();}
    if(a==='new-service'){showModal(`<h2>Novo serviço</h2><p>Cadastre um item adicional para esta demonstração. Ele ficará armazenado apenas neste navegador.</p><form id="service-form"><div class="field"><label>Nome do serviço</label><input name="name" required></div><div class="field-row"><div class="field"><label>Categoria</label><select name="category">${C.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')}</select></div><div class="field"><label>Grupo</label><input name="group" value="Serviços complementares" required></div></div><div class="field-row"><div class="field"><label>Preço sugerido (R$)</label><input name="price" type="number" min="0" step="0.01" required></div><div class="field"><label>Duração demonstrativa (min)</label><input name="duration" type="number" min="15" step="15" value="60" required></div></div><label class="checkline"><input type="checkbox" name="evaluation"> Exige avaliação prévia</label><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn">Salvar serviço</button></div></form>`);}
    if(a==='toggle-active'){A.update(s=>{if(s.inactiveServices.includes(b.dataset.id))s.inactiveServices=s.inactiveServices.filter(x=>x!==b.dataset.id);else s.inactiveServices.push(b.dataset.id);});toast('Disponibilidade do serviço atualizada.');render();}
    if(a==='day-shift'){selectedDate=A.ymd(A.addDays(A.parseDate(selectedDate),Number(b.dataset.shift)));render();}
  });
  document.addEventListener('change',e=>{
    const el=e.target;
    if(el.dataset.action==='overview-date'||el.dataset.action==='agenda-date'){selectedDate=el.value;render();}
    if(el.id==='service-category'){categoryFilter=el.value;render();}
    if(el.dataset.price||el.dataset.duration){const id=el.dataset.price||el.dataset.duration;const base=A.service(id);A.update(s=>{s.serviceOverrides[id]=s.serviceOverrides[id]||{};if(el.dataset.price)s.serviceOverrides[id].price=Number(el.value);if(el.dataset.duration)s.serviceOverrides[id].duration=Number(el.value);});toast('Parâmetro do serviço salvo neste navegador.');}
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='global-search'||e.target.id==='client-search'||e.target.id==='service-search'){
      query=e.target.value;
      const id=e.target.id;const pos=e.target.selectionStart;const keep=id;render();const x=document.getElementById(keep)||document.getElementById('global-search');if(x){x.focus();x.setSelectionRange(pos,pos);}
    }
  });
  document.addEventListener('submit',e=>{
    if(e.target.id==='counter-form'){e.preventDefault();counterSubmit(e.target);}
    if(e.target.id==='queue-form'){e.preventDefault();newQueueSubmit(e.target);e.target.closest('.modal-backdrop')?.remove();}
    if(e.target.id==='package-form'){e.preventDefault();const form=e.target;createPackage(form);form.closest('.modal-backdrop')?.remove();}
    if(e.target.id==='member-form'){e.preventDefault();const form=e.target;addMember(form);form.closest('.modal-backdrop')?.remove();}
    if(e.target.id==='service-form'){e.preventDefault();const form=e.target;addService(form);form.closest('.modal-backdrop')?.remove();}
    if(e.target.id==='absence-form'){e.preventDefault();const form=e.target;handleAbsence(form);form.closest('.modal-backdrop')?.remove();}
    if(e.target.id==='settings-form'){e.preventDefault();const f=new FormData(e.target);A.update(s=>{['open','close','grid','cleaning','delay','cancellationHours','noShowPercent','creditDays','assignment'].forEach(k=>s.config[k]=['open','close','assignment'].includes(k)?f.get(k):Number(f.get(k)));});toast('Parâmetros salvos localmente. Regras configuradas ainda precisam de aprovação do grupo.');render();}
  });
  window.addEventListener('hashchange',()=>{view=(location.hash||'#'+profile.home).slice(1);render();});
  window.addEventListener('aura:state',()=>{if(document.body.classList.contains('admin-app'))render();});
  if(!location.hash)location.hash='#'+profile.home;else render();
})();
